/* @component: form-avatar */
(function () {
  function initUpload() {
    document.querySelectorAll('.form-avatar').forEach(function (container) {
      if (container.dataset.initialized === 'true') return;
      container.dataset.initialized = 'true';
      const dropZone = container.querySelector('.upload-dropzone');
      const fileInput = container.querySelector('input[type="file"]');
      const fileInfo = container.querySelector('.file-info');
      const fileNameDisplay = container.querySelector('.file-name');
      const removeBtn = container.querySelector('.remove-file');
      const avatarIcon = container.querySelector('.avatar-icon');
      const avatarPreview = container.querySelector('.avatar-preview');
      const changeBtn = container.querySelector('.change-btn');
      const fileInfoThumb = container.querySelector('.file-info-thumb');
      if (!dropZone || !fileInput) return;
      function preventDefaults(e) { e.preventDefault(); e.stopPropagation(); }
      ['dragenter', 'dragover', 'dragleave', 'drop'].forEach(function (ev) {
        dropZone.addEventListener(ev, preventDefaults, false);
      });
      ['dragenter', 'dragover'].forEach(function (ev) {
        dropZone.addEventListener(ev, function () { dropZone.classList.add('drag-over'); }, false);
      });
      ['dragleave', 'drop'].forEach(function (ev) {
        dropZone.addEventListener(ev, function () { dropZone.classList.remove('drag-over'); }, false);
      });
      function processCoverPhoto(file) {
        const reader = new FileReader();
        reader.onload = function (e) {
          if (fileInfoThumb) fileInfoThumb.src = e.target.result;
          if (fileNameDisplay) fileNameDisplay.textContent = file.name;
          if (fileInfo) fileInfo.style.display = 'flex';
        };
        reader.readAsDataURL(file);
      }
      function resetCoverUpload() {
        fileInput.value = '';
        if (fileInfo) fileInfo.style.display = 'none';
        if (fileNameDisplay) fileNameDisplay.textContent = '';
        if (fileInfoThumb) fileInfoThumb.src = '';
      }
      function processAvatarPhoto(file) {
        const reader = new FileReader();
        reader.onload = function (e) {
          if (avatarPreview) { avatarPreview.src = e.target.result; avatarPreview.style.display = 'block'; }
          if (avatarIcon) avatarIcon.style.display = 'none';
        };
        reader.readAsDataURL(file);
      }
      function handleFiles(files, cb) {
        if (files && files.length > 0) {
          const file = files[0];
          if (file.type && file.type.indexOf('image/') === 0) cb(file);
        }
      }
      dropZone.addEventListener('drop', function (e) { handleFiles(e.dataTransfer.files, processCoverPhoto); }, false);
      fileInput.addEventListener('change', function (e) { handleFiles(e.target.files, processCoverPhoto); });
      dropZone.addEventListener('click', function (e) { if (e.target !== fileInput) fileInput.click(); });
      if (removeBtn) removeBtn.addEventListener('click', function (e) { e.stopPropagation(); resetCoverUpload(); });
      if (changeBtn) changeBtn.addEventListener('click', function () {
        if (fileInput.files && fileInput.files.length > 0 && fileInput.files[0].type.indexOf('image/') === 0) {
          processAvatarPhoto(fileInput.files[0]);
          resetCoverUpload();
        }
      });
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initUpload);
  } else {
    initUpload();
  }
  setTimeout(initUpload, 300);
})();
/* @end: form-avatar */
